package com.genisource.erp.platform.security;

import org.springframework.boot.context.properties.ConfigurationProperties;

import java.time.Duration;

/**
 * @param adminUsername          account created on first boot
 * @param adminPassword          initial password; a random one is generated by the installer
 * @param adminForcePasswordChange forces a reset right after the first login
 * @param jwt                    signing material and lifetimes
 */
@ConfigurationProperties(prefix = "erp.security")
public record SecurityProperties(
        String adminUsername,
        String adminPassword,
        boolean adminForcePasswordChange,
        Jwt jwt) {

    public record Jwt(String secret, Duration accessTtl, Duration refreshTtl) {

        public Jwt {
            if (accessTtl == null) {
                accessTtl = Duration.ofMinutes(15);
            }
            if (refreshTtl == null) {
                refreshTtl = Duration.ofDays(7);
            }
            if (secret == null || secret.length() < 32) {
                throw new IllegalArgumentException(
                        "erp.security.jwt.secret must be at least 32 bytes (HMAC-SHA256)");
            }
        }
    }

    public SecurityProperties {
        if (adminUsername == null || adminUsername.isBlank()) {
            adminUsername = "admin";
        }
        if (jwt == null) {
            throw new IllegalArgumentException("erp.security.jwt is required");
        }
    }
}
